    def _get_galaxy_server_configs(self):

        output = []
        # Protect against empty/None and filter out empty strings
        server_list = [s for s in (C.GALAXY_SERVER_LIST or []) if s]
        if not server_list:
            return output

        def server_config_def(section, key, required, option_type):
            cfg = {
                'description': 'The %s of the %s Galaxy server' % (key, section),
                'ini': [
                    {
                        'section': 'galaxy_server.%s' % section,
                        'key': key,
                    }
                ],
                'env': [
                    {'name': 'ANSIBLE_GALAXY_SERVER_%s_%s' % (section.upper(), key.upper())},
                ],
                'required': required,
                'type': option_type,
            }
            # Additional defaults/choices as in GalaxyCLI
            if key == 'api_version':
                cfg.update({'default': None, 'choices': [2, 3]})
            elif key == 'timeout':
                cfg.update({'default': C.GALAXY_SERVER_TIMEOUT})
            elif key == 'token':
                cfg.update({'default': None})
            return cfg

        # Definition of server settings: name, required, type
        server_def = [
            ('url', True, 'str'),
            ('username', False, 'str'),
            ('password', False, 'str'),
            ('token', False, 'str'),
            ('auth_url', False, 'str'),
            ('api_version', False, 'int'),
            ('validate_certs', False, 'bool'),
            ('client_id', False, 'str'),
            ('timeout', False, 'int'),
        ]

        for server_key in server_list:
            # Build dynamic configuration definitions for this server
            config_dict = {k: server_config_def(server_key, k, req, typ) for (k, req, typ) in server_def}
            # Register these dynamic definitions under a pseudo plugin type
            C.config.initialize_plugin_configuration_definitions('galaxy_server', server_key, config_dict)

            # Retrieve values and origins for each setting
            server_entries = {}
            for setting in config_dict.keys():
                try:
                    v, o = C.config.get_config_value_and_origin(
                        setting,
                        cfile=self.config_file,
                        plugin_type='galaxy_server',
                        plugin_name=server_key,
                        variables=get_constants(),
                    )
                except AnsibleError as e:
                    if to_text(e).startswith('No setting was provided for required configuration'):
                        v = None
                        o = 'REQUIRED'
                    else:
                        raise

                if v is None and o is None:
                    o = 'REQUIRED'

                server_entries[setting] = Setting(setting, v, o, None)

            # Render settings similarly to plugin configs
            results = self._render_settings(server_entries)
            if results:
                if context.CLIARGS['format'] == 'display':
                    output.append('\n%s:\n%s' % (server_key, '_' * len(server_key)))
                    output.extend(results)
                else:
                    output.append({server_key: results})

        return output

